const text = $input.first().json.text || '';
const documentName = 'FRMCS Functional Requirements Specification (FU-7120)';
const stakeholderType = 'Standards body';
const documentSection = 'Section 10.11 - Railway Emergency Communication';

// Character-based chunking with overlap
// Fallback works for any document format including 10.11.x.x numbering
const chunkSize = 3000;
const overlap = 200;
const chunks = [];

for (let i = 0; i < text.length; i += chunkSize - overlap) {
  const chunk = text.slice(i, i + chunkSize);
  if (chunk.trim().length > 0) {
    chunks.push(chunk.trim());
  }
}

return chunks.map((chunk, i) => ({
  json: {
    chunkIndex: i,
    totalChunks: chunks.length,
    text: chunk,
    documentName,
    stakeholderType,
    documentSection
  }
}));

const items = $input.all();
const allRequirements = [];

for (const item of items) {
  // Extract the text from the GPT-4o response
  const text = item.json?.output?.[0]?.content?.[0]?.text || '';
  const content = text.replace(/```json|```/g, '').trim();

  // Skip empty responses
  if (!content || content === '[]') continue;

  try {
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed)) {
      allRequirements.push(...parsed);
    }
  } catch(e) {
    // Skip malformed chunks silently
  }
}

return allRequirements.map(r => ({ json: r }));

const items = $input.all();

// Filter out any error items and items without valid id or text
const validItems = items.filter(item => 
  item.json.id && 
  item.json.text && 
  !item.json.error
);

// Renumber IDs sequentially as REQ-001, REQ-002 etc.
const reqs = validItems.map((item, index) => ({
  id: `REQ-${String(index + 1).padStart(3, '0')}`,
  text: item.json.text || '',
  sourcePassage: item.json.sourcePassage || '',
  sourceDoc: item.json.sourceDoc || '',
  sourceSection: item.json.sourceSection || '',
  sourceRef: item.json.sourceRef || null,
  stakeholderType: item.json.stakeholderType || '',
  abstractionLevel: item.json.abstractionLevel || '',
  ambiguityFlag: item.json.ambiguityFlag || 'no'
}));

return [{ json: { allRequirements: JSON.stringify(reqs) } }];

const first = $input.first().json;
const text = first?.output?.[0]?.content?.[0]?.text || '';
const content = text.replace(/```json|```/g, '').trim();

let reqArray = [];
try {
  const parsed = JSON.parse(content);
  reqArray = Array.isArray(parsed) ? parsed : [parsed];
} catch(e) {
  return [{ json: { error: e.message, raw: content.slice(0, 300) } }];
}

return reqArray.map(r => ({ json: r }));
